def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # The most frequent color is the background; enclosed rectangular rings
    # of other colors indicate regions to fill.
    counts = [sum(row.count(c) for row in grid) for c in range(10)]
    background = max(range(10), key=lambda c: counts[c])
    seen = set()

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue

            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            r0 = min(y for y, x in cells)
            r1 = max(y for y, x in cells)
            c0 = min(x for y, x in cells)
            c1 = max(x for y, x in cells)
            if r1 - r0 < 2 or c1 - c0 < 2:
                continue

            # Only fill components that form a complete rectangular outline.
            border = {
                (y, x)
                for y in range(r0, r1 + 1)
                for x in range(c0, c1 + 1)
                if y in (r0, r1) or x in (c0, c1)
            }
            if set(cells) != border:
                continue

            inner_h = r1 - r0 - 1
            inner_w = c1 - c0 - 1
            fill = 7 if inner_h % 2 == 1 and inner_w % 2 == 1 else 2
            for y in range(r0 + 1, r1):
                for x in range(c0 + 1, c1):
                    out[y][x] = fill

    return out
